      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "maj7",
      "function_role": "shell-voicing-floor",
      "narrative": "Use shell voicings \u2014 root, 3rd, and 7th \u2014 as the minimum needed to define the Maj7 sound. Drop the 5th entirely; it does not compromise the chord's essential character and frees a voice for melody or extensions. (Chapter 5, p.145)",
      "source_principle_ids": [
        "shell-voicing-floor",
        "note-omission-policy"
      ],
      "source_work_id": "complete-chord-melody",
      "references": [
        {
