      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "min7b5",
      "function_role": "sub-family-discrimination",
      "narrative": "Never substitute plain min7 for min7b5 when the progression demands it \u2014 the harmonic situation will sound wrong. Keep min7b5 (and its extension Cm11b5) as a distinct sub-family separate from the 'm7' family. (Chapter 3, p.23)",
      "source_principle_ids": [
        "sub-family-discrimination"
      ],
      "source_work_id": "complete-chord-melody",
      "references": [
