      "function_role": "sub-family-discrimination",
      "narrative": "Never substitute a natural dominant (dom7, dom9, dom13) for dom7b9 when the progression demands altered color \u2014 the wrong sub-family will sound wrong. Commit to the altered dominant voicing whenever the harmonic situation specifies it. (Chapter 3, p.23)",
      "source_principle_ids": [
        "sub-family-discrimination"
      ],
      "source_work_id": "complete-chord-melody",
      "references": [
